const { ZXFonts8x8 } = await import('./svision/js/platform/canvas2D/zx/zxFonts8x8.js?ver='+window.srcVersion);
// begin code

/**
 * The character set of Space Invaders as a svision 8x8 font, in the shape of
 * ZXFonts8x8: the same 96-character set and a glyph table of 16 hex digits per
 * character, so TextEntity, MenuEntity and the ZX dialogs render it like any
 * other font.
 *
 * The table is generated by tools/rom2font.py: 0-9, A-Z, < > = * ? - and the
 * space are the ROM's own characters (1E00h, data/font.json), moved up from
 * rows 1-7 to rows 0-6; everything else comes from "The Island" (1984, Crystal
 * Computing) of ~/sw/zx-fonts, the one ZX Spectrum font whose letters and
 * digits are pixel for pixel the Space Invaders ones (0 differences over the
 * 36 glyphs), so the two halves are one design; © is drawn by hand in the
 * same style (The Island has none). One extra glyph: '⅄', the upside-down Y
 * of the attract mode ("PLAY SPACE INVADERS" before the alien fixes it).
 *
 * Monospace: 8-pixel cells as on the machine; proportional trims them like
 * the ZX font.
 */
export class SpaceInvadersFonts8x8 extends ZXFonts8x8 {

  /**
   * @param {Object} app - The application instance.
   * @param {boolean} proportional - Trim the glyphs to proportional widths; false keeps the 8-pixel cells.
   */
  constructor(app, proportional) {
    super(app, proportional);
    this.id = 'SpaceInvadersFonts8x8';

    this.setFontsData('');
    this.addGlyphs('⅄', '1010101028444400');   // the upside-down Y of the attract
  } // constructor

} // SpaceInvadersFonts8x8
